style.css:
@-moz-document url("https://www.google.com/") {
/* Hide the new Google logo */
  img[alt="Google"], .lnXdpd, svg {
    display: none !important;
  }

  /* Insert old Google logo */
  body::before {
    content: "";
    display: block;
    background-image: url('https://upload.wikimedia.org/wikipedia/commons/2/2f/Google_2010_logo.png'); /* Old logo */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 100%;
    height: 200px;
    margin-top: 140px;
  }

  /* Dark background */
  body {
    background-color: #121212 !important;
  }

  /* Optional: style the search bar */
  input.gLFyf {
    background-color: #1e1e1e !important;
    color: white !important;
    border: 1px solid #444 !important;
  }

  /* Optional: style the buttons */
  input[type="submit"] {
    background-color: #333 !important;
    color: white !important;
    border: none !important;
  }
}
